from __future__ import annotations

from minidb.types import (
    COMPARISON_OPS,
    And,
    ColumnDef,
    ColumnRef,
    ColumnType,
    Comparison,
    CreateTableStmt,
    DeleteStmt,
    DropTableStmt,
    Expr,
    InsertStmt,
    IsNull,
    Literal,
    Not,
    Or,
    SelectStmt,
    SQLSyntaxError,
    Statement,
    Token,
    TokenType,
    Value,
)

__all__ = ["parse", "parse_script", "parse_expression"]


def parse(tokens: list[Token]) -> Statement:
    """Parse exactly one statement, optionally followed by a single ';',
    then EOF.

    Raises:
        SQLSyntaxError: if the tokens are not exactly one valid statement
            (including empty input, a lone ';', or trailing tokens).
    """
    def _parse_keyword(expected: str) -> Token:
        token = tokens.pop(0)
        if token.type != TokenType.KEYWORD or token.value != expected:
            raise SQLSyntaxError(f"Expected keyword '{expected}', got {token}")
        return token

    def _parse_identifier() -> Token:
        token = tokens.pop(0)
        if token.type != TokenType.IDENTIFIER:
            raise SQLSyntaxError(f"Expected identifier, got {token}")
        return token

    def _parse_literal() -> Literal:
        token = tokens.pop(0)
        if token.type == TokenType.INTEGER:
            return Literal(int(token.value))
        elif token.type == TokenType.STRING:
            return Literal(token.value)
        elif token.type == TokenType.KEYWORD and token.value == "TRUE":
            return Literal(True)
        elif token.type == TokenType.KEYWORD and token.value == "FALSE":
            return Literal(False)
        elif token.type == TokenType.KEYWORD and token.value == "NULL":
            return Literal(None)
        else:
            raise SQLSyntaxError(f"Expected literal, got {token}")

    def _parse_column_def() -> ColumnDef:
        name = _parse_identifier().value
        _parse_keyword("INTEGER")
        return ColumnDef(name, ColumnType.INTEGER)

    def _parse_column_defs() -> tuple[ColumnDef, ...]:
        _parse_keyword("(")
        defs = [_parse_column_def()]
        while tokens[0].value == ",":
            tokens.pop(0)
            defs.append(_parse_column_def())
        _parse_keyword(")")
        return tuple(defs)

    def _parse_column_names() -> tuple[str, ...]:
        _parse_keyword("(")
        names = [_parse_identifier().value]
        while tokens[0].value == ",":
            tokens.pop(0)
            names.append(_parse_identifier().value)
        _parse_keyword(")")
        return tuple(names)

    def _parse_values() -> tuple[Value, ...]:
        _parse_keyword("VALUES")
        _parse_keyword("(")
        values = [_parse_literal().value]
        while tokens[0].value == ",":
            tokens.pop(0)
            values.append(_parse_literal().value)
        _parse_keyword(")")
        return tuple(values)

    def _parse_select_columns() -> Optional[tuple[str, ...]]:
        if tokens[0].value == "*":
            tokens.pop(0)
            return None
        columns = [_parse_identifier().value]
        while tokens[0].value == ",":
            tokens.pop(0)
            columns.append(_parse_identifier().value)
        return tuple(columns)

    def _parse_where() -> Optional[Expr]:
        if tokens[0].type == TokenType.KEYWORD and tokens[0].value == "WHERE":
            tokens.pop(0)
            return parse_expression(tokens)
        return None

    def _parse_create_table() -> CreateTableStmt:
        _parse_keyword("CREATE")
        _parse_keyword("TABLE")
        table_name = _parse_identifier().value
        columns = _parse_column_defs()
        _parse_keyword(";")
        return CreateTableStmt(table_name, columns)

    def _parse_drop_table() -> DropTableStmt:
        _parse_keyword("DROP")
        _parse_keyword("TABLE")
        table_name = _parse_identifier().value
        _parse_keyword(";")
        return DropTableStmt(table_name)

    def _parse_insert() -> InsertStmt:
        _parse_keyword("INSERT")
        _parse_keyword("INTO")
        table_name = _parse_identifier().value
        columns = None
        if tokens[0].value == "(":
            columns = _parse_column_names()
        values = _parse_values()
        _parse_keyword(";")
        return InsertStmt(table_name, columns, values)

    def _parse_select() -> SelectStmt:
        _parse_keyword("SELECT")
        columns = _parse_select_columns()
        _parse_keyword("FROM")
        table_name = _parse_identifier().value
        where = _parse_where()
        _parse_keyword(";")
        return SelectStmt(table_name, columns, where)

    def _parse_delete() -> DeleteStmt:
        _parse_keyword("DELETE")
        _parse_keyword("FROM")
        table_name = _parse_identifier().value
        where = _parse_where()
        _parse_keyword(";")
        if where is None:
            where = Literal(True)
        return DeleteStmt(table_name, where)

    if not tokens:
