    def _parse_primary() -> Expr:
        token = tokens.pop(0)
        if token.type == TokenType.INTEGER:
            return Literal(int(token.value))
        elif token.type == TokenType.STRING:
            return Literal(token.value)
        elif token.type == TokenType.KEYWORD and token.value == "TRUE":
            return Literal(True)
        elif token.type == TokenType.KEYWORD and token.value == "FALSE":
            return Literal(False)
        elif token.type == TokenType.KEYWORD and token.value == "NULL":
            return Literal(None)
        elif token.type == TokenType.IDENTIFIER:
            return ColumnRef(token.value)
        elif token.type == TokenType.OPERATOR and token.value == "(":
            expr = parse_expression(tokens)
            _parse_operator(")")
            return expr
        else:
            raise SQLSyntaxError(f"Expected primary, got {token}")

    def _parse_is_null(negated: bool) -> IsNull:
        operand = _parse_primary()
        return IsNull(operand, negated)

    def _parse_predicate() -> Expr:
        expr = _parse_primary()
        if tokens[0].type == TokenType.KEYWORD and tokens[0].value == "IS":
            tokens.pop(0)
            if tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NOT":
                tokens.pop(0)
                return _parse_is_null(negated=True)
            elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NULL":
                tokens.pop(0)
                return _parse_is_null(negated=False)
            else:
                raise SQLSyntaxError(f"Expected NULL or NOT NULL, got {tokens[0]}")
        elif tokens[0].value in COMPARISON_OPS:
            op = _parse_operator()
            right = _parse_primary()
            return Comparison(op, expr, right)
        else:
            return expr

    def _parse_not_expr() -> Expr:
        if tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NOT":
            tokens.pop(0)
            operand = _parse_not_expr()
            return Not(operand)
        else:
            return _parse_predicate()

    def _parse_and_expr() -> Expr:
        expr = _parse_not_expr()
        while tokens[0].type == TokenType.KEYWORD and tokens[0].value == "AND":
            tokens.pop(0)
            right = _parse_not_expr()
            expr = And(expr, right)
        return expr

    def _parse_or_expr() -> Expr:
        expr = _parse_and_expr()
        while tokens[0].type == TokenType.KEYWORD and tokens[0].value == "OR":
            tokens.pop(0)
            right = _parse_and_expr()
            expr = Or(expr, right)
        return expr

    def _parse_operator(expected: Optional[str] = None) -> str:
        token = tokens.pop(0)
        if token.type != TokenType.OPERATOR:
            raise SQLSyntaxError(f"Expected operator, got {token}")
        if expected and token.value != expected:
            raise SQLSyntaxError(f"Expected operator '{expected}', got {token}")
        return token.value

    if not tokens:
        raise SQLSyntaxError("Empty token stream")

    expr = _parse_or_expr()

    if tokens[0].type != TokenType.EOF:
        raise SQLSyntaxError(f"Trailing tokens: {tokens}")

    return expr

